export function mergeBygoneData(serverData: BygoneDataset | null | undefined): BygoneFloorItem[] {
  if (!serverData || !Array.isArray(serverData.floors) || serverData.floors.length === 0) {
    return BASELINE_BYGONE_FLOORS;
  }

  const baselineMap = new Map(BASELINE_BYGONE_FLOORS.map((f) => [f.floor, f]));

  return serverData.floors.map((sfRaw) => {
    const sf = sfRaw as any;
    const fallback = baselineMap.get(sf.floor) || ({} as Partial<BygoneFloorItem>);
    const prim = sf.primary_enemy as any;
    const hpStacks = typeof sf.hp_buff_stacks === 'number' ? sf.hp_buff_stacks : (fallback.hp_buff_stacks ?? 0);
    const atkStacks = typeof sf.atk_buff_stacks === 'number' ? sf.atk_buff_stacks : (fallback.atk_buff_stacks ?? 0);
    const dispDiff = typeof sf.displayed_difficulty === 'number' ? sf.displayed_difficulty : (fallback.displayed_difficulty ?? (hpStacks + 100));

    return {
      floor: sf.floor,
      is_boss_floor: Boolean(sf.is_boss_floor ?? fallback.is_boss_floor),
      is_duplicate: Boolean(sf.is_duplicate ?? fallback.is_duplicate),
      duplicated_from_floor: typeof sf.duplicated_from_floor === 'number' ? sf.duplicated_from_floor : (fallback.duplicated_from_floor ?? null),
      hp_buff_stacks: hpStacks,
      atk_buff_stacks: atkStacks,
      displayed_difficulty: dispDiff,
      monster_level: typeof sf.monster_level === 'number' ? sf.monster_level : (fallback.monster_level ?? 70),
      round_gs: typeof sf.round_gs === 'number' ? sf.round_gs : (fallback.round_gs ?? 0),
      final_hp: typeof sf.final_hp === 'number' ? sf.final_hp : (fallback.final_hp ?? 0),
      final_atk: typeof sf.final_atk === 'number' ? sf.final_atk : (fallback.final_atk ?? 0),
      weakness: Array.isArray(sf.weakness) && sf.weakness.length > 0
        ? sf.weakness.map((w: any) => ({
            element: w.element || '',
            element_name_en: w.element_name_en || w.element || '',
            element_name_ru: w.element_name_ru || w.element_name_en || w.element || '',
            name_en: w.name_en || '',
            name_ru: w.name_ru || w.name_en || '',
            icon: w.icon || null,
          }))
        : (fallback.weakness || []),
      primary_enemy: prim
        ? {
            canonicalEnemyId: prim.canonicalEnemyId || fallback.primary_enemy?.canonicalEnemyId || '',
            name_en: prim.name_en || prim.name || fallback.primary_enemy?.name_en || '',
            name_ru: prim.name_ru || prim.name_en || prim.name || fallback.primary_enemy?.name_ru || '',
            element: prim.element || fallback.primary_enemy?.element || 'None',
            is_boss: Boolean(prim.is_boss ?? fallback.primary_enemy?.is_boss),
            image: prim.image || fallback.primary_enemy?.image || null,
            imageThumb: prim.imageThumb || fallback.primary_enemy?.imageThumb || null,
          }
        : (fallback.primary_enemy || null),
    };
  });
}
